--
-- Dumping data for table `ep_jobs`
--

INSERT INTO `ep_jobs` (`id`, `title`, `position`, `timing_ref_id`, `description`, `status`, `inserted_date`, `inserted_time`, `inserted_by`, `updated_date`, `updated_time`, `updated_by`) VALUES
(1, 'Experienced Cleaners Required for Our NDIS Clients', 'Cleaner ', '2', 'We are looking to hire cleaners for our NDIS clients.\n\nThe location must be the Melbourne metropolitan area.\n\nTo be successful for the position, you must demonstrate:\n- Valid driving license along with a reliable car.\n- Valid National Police Check\n- Cleaning experience.\n- Must be competent in written and verbal communication\n- Providing 100 documents are essential\n- Based on the performance of the support worker, company may consider a full time position.\n  \n  Benefits\n- Competitive pay per hour plus super\n- Industry training\n- Networking\n\nIf you meet the above requirements and ready to start a rewarding career please feel free to apply.', 'active', '2020-11-29', '01:52:32 PM', '1', '2020-11-29', '01:55:28 PM', '1'),
(2, 'Turkish Speaking Support Worker', 'Support Worker', '2', 'We are looking to hire a Turkish speaking support worker.\n\nThe location must be St Kilda, South Melbourne, Park Dale Area.\n\nTo be successful for the position, you must demonstrate:\n\n- Valid driving license along with a reliable car.\n- Valid National Police Check\n- Relevant qualification\n- Must be competent in written and verbal communication.\n- Providing 100 documents are essential\n\nBased on the performance of the support worker, company may consider a full time position.\n\nBenefits\n- Competitive pay per hour plus super\n- Industry training\n- Networking\n\nIf you meet the above requirements and ready to start a rewarding career please feel free to apply.', 'active', '2020-11-30', '08:28:47 AM', '1', NULL, NULL, NULL),
(3, 'Support Worker Required with IT Related Background ', 'Support Worker ', '4', 'We are looking for a support worker who has an IT-related background for our NDIS clients preferably female and who is tech-savvy and able to mentor. \n\nThe selected candidate will assist our client in accessing the community. The client has a special interest in fishing and horticulture, gardening, bushwalking (gardens and nature).\n\nThe worker must have full knowledge of the following:\nApple Products\nAndroid Applications\nWindows and computer-related stuff.\nApplications like MS Office and setting up the computer for first use etc.\n\nTo be successful for the position, you must demonstrate:\nValid driving license along with a reliable car.\nValid National Police Check\nMust be competent in written and verbal communication\nProviding 100 documents are essential\n\nBased on the performance of the support worker, the company may consider a full-time position.\n\nBenefits:\nCompetitive pay per hour plus super\nIndustry training\nNetworking\n\nIf you meet the above requirements and ready to start a rewarding career please feel free to apply.', 'active', '2020-12-23', '12:24:53 PM', '1', '2021-01-05', '10:01:15 AM', '1'),
(4, 'Disability Support Worker Required', 'Support Worker', '4', 'We are currently looking for support workers with support worker experience from Melbourne/Inner east areas.\nTo be successful for the position, you must demonstrate:\n- Valid driving license along with reliable car\n- Valid National Police Check\n- Relevant qualifications like certificate 3 or certificate 4 related to disability.\n- Must be competent in written and verbal communication\n- Providing 100 documents are essential\nBased on the performance of the support worker, the company may consider a full-time position.\nBenefits\n- Competitive pay per hour plus super\n- Industry training\n- Networking\nIf you meet the above requirements and ready to start a rewarding career please fill out the Support Worker Application Form.', 'active', '2021-01-27', '09:40:56 AM', '1', NULL, NULL, NULL);

