(10, '', '', 'Neil Magallon', 'Neil Magallon', NULL, NULL, 'U 2015, 199 William Street, Melbourne VIC', 'Melbourne', '2', '3000', '16', '0433984022', 'imneilthegreat@gmail.com', 'NA', '21-11-1994', NULL, NULL, 'Neil', 'Magallon', NULL, 'U 2015, 199 William Street', 'Melbourne', '2', '3000', '16', 'Social Media (Facebook / Twitter / LinkedIn)', NULL, 'yes', 'My responsibilities as a support worker in an aged care facility are the following:\nâ—	Undertake activities of daily living including; maintaining hygiene, feeding, bathing, dressing and undressing, as well as toileting.\nâ—	Physically move and transport patients into and out of bed and other areas within the facility. \nâ—	Assist in administering daily medication to patients as prescribed.\nâ—	Carried out allocated general cleaning duties like changing bed sheets and restocking rooms with necessary supplies achieving established standards of cleanliness and presentation to meet patientsâ€™ needs and exceed their expectations in regards to the cleanliness of the facility.\nâ—	Responded with enthusiasm in carrying out any other additional reasonable duty tasked to assist in the smooth running of the facility.\nâ—	Conduct behavioural management is a kind and respectful manner.\n', 'no', NULL, NULL, NULL, NULL, 'Personal Care,Help In The Community,Help At Home,Education / Training / Employment Support', 'Mealtime Assistance & Feeding', 'No I do not currently work for any disability service provider.', NULL, NULL, NULL, '2', NULL, '16', NULL, NULL, NULL, '2', NULL, '16', 'U 2015, 199 William Street', 'Melbourne', '2', '3000', '16', 'imneilthegreat@gmail.com', '0433984022', 'no', NULL, 'no', NULL, 'no', 'no', NULL, '{\"day\":{\"1\":\"Monday\",\"2\":\"Tuesday\",\"3\":\"Wednesday\",\"4\":\"Thursday\",\"5\":\"Friday\",\"6\":\"Saturday\",\"7\":\"Sunday\"},\"not_available\":{\"1\":true,\"2\":true,\"3\":false,\"4\":false,\"5\":false,\"6\":false,\"7\":false},\"from\":{\"1\":\"-\",\"2\":\"-\",\"3\":\"2021-01-04T21:00:0