(75, '', '', 'Holly ', 'Robinson-Pereira ', NULL, NULL, '29 Camden Street ', 'Balaclava ', '2', '3183', '16', '0423936673', 'robbopereira@gmail.com ', 'live:.cid.c9a90e0c06550feb', '03-09-1989', NULL, NULL, 'Nicole', 'Abeyratne', NULL, '29 Camden Street ', 'Balaclava ', '2', '3183', '16', 'Internet Search e.g., Google', '', 'no', '', '', '', '', 'I have always been passionate about helping others, in whatever way I can at any certain time.  My calling in life is to be a social worker for youth. As I have seen a lot of people go down the wrong path. \nThere is a lack of support for youth in the world today.  A lack of understanding for mental health and social issues. \nIm keen to finally work somewhere i can feel rewarded for my work. \n:) kindly, \nHolly', '', 'Personal Care,Help At Home,Help In The Community,Specialised Support Services,Therapy Support', 'Anaphylaxis,Bowel Care,Behaviour Management,Catheter or Condom Drainage,Epilepsy or Seizure,Diabetes Assistance,Wound / Pressure Care,Ventilator Care,Mealtime Assistance & Feeding,Medication Administration', 'No I do not currently work for any disability service provider.', '', '', '', '2', '', '16', '', '', '', '2', '', '16', '29 Camden Street ', 'Balaclava ', '2', '3183 ', '16', 'robbopereira@gmail.com ', '0423936673', 'no', '', 'no', '', 'no', 'no', 'yes', '{\"day\":{\"1\":\"Monday\",\"2\":\"Tuesday\",\"3\":\"Wednesday\",\"4\":\"Thursday\",\"5\":\"Friday\",\"6\":\"Saturday\",\"7\":\"Sunday\"},\"from\":{\"1\":\"8am\",\"2\":\"8am\",\"3\":\"8am\",\"4\":\"8am\",\"5\":\"-\",\"6\":\"-\",\"7\":\"11am\"},\"to\":{\"1\":\"To - 7pm\",\"2\":\"To- 7pm\",\"3\":\"To - 7pm\",\"4\":\"To - 6pm\",\"5\":\"-\",\"6\":\"-\",\"7\":\"To - 4pm\"},\"not_available\":{\"1\":false,\"2\":false,\"3\":false,\"4\":false,\"5\":true,\"6\":false,\"7\":false}}', 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday', '8am,8am,8am,8am,-,-,11am', 'To - 7pm,To- 7pm,To - 7pm,To - 6pm,-,-,To - 4pm', ',,,,1,,', 'yes', '', '', '', '', '', '', '', '', '', '', 'Female', '', 'no', 'yes', 'yes', '16', '', 'yes', '', '', '', 'no', 'I have worked before but am not currently working', '', '', '', '2', '', '16', '555 Flinders Street ', 'Melbourne ', '2', '3000', '16', '', '', 'Apartments of Melbourne ', '2019', 'Cleaning Supervisor ', 'Learning how to manage a team of 7 young women . Challenging and I gained experience and confidence as a supervisor.  Gained the girls respect and trust, after learning the happy medium between being kind and strict.  Friendly but serious. \nBecause I was tested and undermined. Until i had the moment I realised I had succeeded in my personal goals as a supervisor for the first time  . A great opportunity overall. \n\nUnfortunately my old boss has gone into liquidation.  I just read as I looked up the postcode. \nThanks,  \nHolly.', 'yes', '{\"name_of_referee\":{\"1\":\"Charlie Mazza\",\"2\":\"Justin Dowd\"},\"organisation\":{\"1\":\"J & L Meats, Prahran Market \",\"2\":\"CABRINI Elsternwick \"},\"position_held\":{\"1\":\"Manager\",\"2\":\"Hotel Services Manager \"},\"contact_no\":{\"1\":\"98275181\",\"2\":\"95081222\"},\"email_address\":{\"1\":\"N\\/A\",\"2\":\"Jdowd@cabrini.com.au\"}}', '98275181,95081222', 'N/A,Jdowd@cabrini.com.au', 'Charlie Mazza,Justin Dowd', 'J & L Meats, Prahran Market ,CABRINI Elsternwick ', 'Manager,Hotel Services Manager ', 'no', '', '', '', '', '', 'no', '', '', '', '', '', '', '', '', '', '', '', 'yes', '75-372d-holly-cv-2021.docx', 'no', '', 'no', '', '', 'no', '', 'no', '', '', 'no', '', 'no', '', '', 'no', '', 'no', '', 'no', '', 'no', '', 'no', '', 'no', '', 'no', '', 'no', '', 'no', '', '', '', 'yes', '75-3979-Holly-RESUME-cleaning-2021.docx', 'true', '6', '\"Don\'t have driver license and car\" ', NULL, NULL, NULL, '2021-03-12', '12:46:51 PM', '', '2021-03-12', '01:51:33 PM', ''),
