(140, '', '4', 'Arthur ', 'Digman ', '0414167713', '', '55 Childs Street ', 'Melton South ', '2', '3338', '16', '0432664188', 'arthur0digman@gmail.com', 'arthur0digman@outlook.com', '29-09-1984', NULL, NULL, 'Edwin ', 'Nepacena ', 'Friend ', '4 Euroa Walk', 'Kurunjang ', '2', '3337', '16', 'Authentic Life Care Support Worker', '', 'yes', 'I am working as a Disability Support Worker in an SRS facility. I have also had placements in the National Centre for Mental Health and TLC Marina Aged Care.  \r\n\r\nI have finished Certificate III in Individual Support and I am on my first year in Diploma of Nursing at Stott\'s College in Melbourne where we are taught the necessary core skills and knowledge of practices providing first-hand services to vulnerable people in our society. \r\n\r\nI have the experience of providing quality care and sound practices towards the vulnerable members in our community particularly the elderly, people at risk of homelessness, people who have a disability, and people who have mental illnesses.\r\n\r\nI help provide holistic care even though my experience at work was in Supported Residential Services (SRS). I have experience working in a diverse setting wherein employees have sound understanding and respect of different cultures including cultural safety of elderly and people with disability especially of diverse backgrounds.\r\n\r\nI have excellent communication skills and the ability to engage with the elderly with my patience and empathy. I am a quick learner and can work independently and at the same time, I can work collaboratively with other staff and professionals.\r\n\r\nI would like to work at your company because I believe that my knowledge, skills, and experience are a good fit for your organization. I would be glad to have the opportunity to talk with you more about this position, and how I could use my skills to benefit your company.\r\n\r\n', 'no', '', '', '', '', 'Personal Care,Help At Home,Specialised Support Services', 'All Specialised Support Services', 'Yes I currently work for one or more other disability services providers', 'Rehmat Sandhu Foundation ', '7 Summer Court ', 'Melton West ', '2', '3337', '16', '', '', '', '2', '', '16', '55 Childs Street', 'Melton South ', '2', '3338', '16', 'arthur0digman@gmail.com', '0432664188', 'no', '', 'no', '', 'yes', 'yes', 'yes', '{\"day\":{\"1\":\"Monday\",\"2\":\"Tuesday\",\"3\":\"Wednesday\",\"4\":\"Thursday\",\"5\":\"Friday\",\"6\":\"Saturday\",\"7\":\"Sunday\"},\"from\":{\"1\":\"05:00 PM\",\"2\":\"05:00 PM\",\"3\":\"05:00 PM\",\"4\":\"05:00 PM\",\"5\":\"05:00 PM\",\"6\":\"08:00 AM\",\"7\":\"07:00 AM\"},\"to\":{\"1\":\"07:00 AM\",\"2\":\"07:00 AM\",\"3\":\"07:00 AM\",\"4\":\"07:00 AM\",\"5\":\"07:00 AM\",\"6\":\"12:30 PM\",\"7\":\"03:30 PM\"},\"not_available\":{\"1\":false,\"2\":false,\"3\":false,\"4\":false,\"5\":false,\"6\":false,\"7\":false}}', 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday', '05:00 PM,05:00 PM,05:00 PM,05:00 PM,05:00 PM,08:00 AM,07:00 AM', '07:00 AM,07:00 AM,07:00 AM,07:00 AM,07:00 AM,12:30 PM,03:30 PM', ',,,,,,', 'no', 'yes', '', 'Visa 500', '', '', 'P5984938A', 'PHILIPPINES ', 'None', '09-02-2018', '08-02-2028', 'Male', '', 'no', 'yes', 'no', '186', '', 'yes', 'Filipino', '', '', 'no', 'I am currently working', 'Warranvale Gardens SRS', '314 Reynolds Road ', 'Donvale ', '2', '3111', '16', '2-10 Bridge Road ', 'Melton South ', '2', '3338', '16', 'Disability Support Worker ', 'I became proficient in providing a person and strength-based approach to the care of clients.  I make sure that the vulnerable members of our society: aged, disabled, homeless, and victims of crime will receive the support and assistance they deserve. ', 'Meadowbrook SRS', '2022', 'Disability Support Worker (Sleepover)', 'I am able to impart my knowledge and expertise in providing a person-centred and strength-based approach to the care of clients. I make sure that the vulnerable members of our society: aged, disabled, homeless, and victims of crime will receive the support and assistance they deserve. I’m a dependable and caring Disability Support Worker in the healthcare industry. \r\n\r\nI care and advocate for clients mainly who are inside the bracket of being elderly and people who have mental illnesses and disabilities:  Bipolar disorder, Delusional, Substance Dependence (Drug-induced), Depression, Schizophrenia, and ABI (Acquired Brain Injury).  I have excellent communication skills, I am compassionate, a quick thinker, and able to work in a busy environment. ', 'yes', '[]', '', '', '', '', '', 'no', '', '', '', '', '', 'yes', 'Certificate', '', 'Certificate III in Individual Support', '2021', 'Stott\'s College, Melbourne', 'yes', 'Diploma', '', 'Diploma of Nursing ', '2023', 'Stott\'s College, Melbourne', 'yes', '140-68fe-Arthur-DIGMAN-Cover-Letter-&-Resume--Disability-Support.docx', 'yes', '', 'yes', '', '', 'no', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', 'no', '', '', '', '', '', '', '', '', '', '', '', '', '', 'true', '3', NULL, NULL, NULL, NULL, '2022-02-16', '12:54:34 PM', '', '2022-02-22', '10:21:33 AM', '2'),
(141, NULL, '3', 'Dilpreet', 'Kaur', '0481544639', 'siingh707@gmail.com', '10/219 Mahoneys Rd ', 'Forest hill', '2', '3131', '16', '0468808637', 'siingh707@gmail.com', 'S4517279@outlook.com', '20-07-1996', NULL, NULL, 'Dilpreet', 'Kaur', 'Wife', '10/219 Mahoneys Rd Forest Hill', 'Forest hill', '2', '3131', '16', 'Internet Search e.g., Google', NULL, 'yes', 'Worked as DSW for more than 5 years my experiences are as follow:\r\n1:- Disability Support Worker\r\nAccomodation and Care Solution\r\n04/2016 - 03/2020\r\n My work at this workplace encompasses holistic care for a young patient with acquired brain injury. I also provide him with his personal care and occasional trips for outdoor activities.\r\n\r\n2:- DSW\r\nCare For You\r\n03/2015 - 06/2019\r\nMy work at this workplace includes holistic care for a young patient with a spinal cord injury and resulting quadriplegia. I also provide him with his personal care and occasional trips for outdoor activities.\r\nAssisted Clients in daily personal care, toileting, clothing care, household duties and transportation.\r\nWorked with family, health care providers, therapists, and social workers to ensure all necessary clients needs were met.', 'no', NULL, NULL, NULL, NULL, 'Help At Home,Help In The Community,Education / Training / Employment Support,Transport Assistance,Personal Care,All Support Services', 'Catheter or Condom Drainage,Bowel Care,Wound / Pressure Care,Ventilator Care,PEG (Percutaneous Endoscopic Gastronomy),Manual Handling (Lifting / Hoisting / Transfers),Mealtime Assistance & Feeding,Medication Administration', 'No I do not currently work for any disability service provider.', NULL, NULL, NULL, '2', NULL, '16', NULL, NULL, NULL, '2', NULL, '16', '10/219 Mahoneys Rd ', 'Forest hill', '2', '3131', '16', 'siingh707@gmail.com', '0468808637', 'no', NULL, 'no', NULL, 'yes', 'yes', 'yes', '{\"day\":{\"1\":\"Monday\",\"2\":\"Tuesday\",\"3\":\"Wednesday\",\"4\":\"Thursday\",\"5\":\"Friday\",\"6\":\"Saturday\",\"7\":\